// Class 11 Chemistry Flashcards — 3 chapters × 40 cards = 120 total
import type { Class11Flashcard } from "./flashcards-physics";

export const CHEMISTRY_FLASHCARDS: Class11Flashcard[] = [
  // ===== SOME BASIC CONCEPTS OF CHEMISTRY (c1) — 40 cards =====
  { id: "chem11-c1-mole-001", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "definition", front: "What is a mole?", back: "The amount of substance that contains as many entities (atoms/molecules/ions) as there are atoms in exactly 12 g of carbon-12.", difficulty: "easy", examImportance: "high", tags: ["mole", "basics"] },
  { id: "chem11-c1-mole-002", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "definition", front: "What is Avogadro's number?", back: "6.022 × 10²³ — the number of entities in 1 mole of any substance.", difficulty: "easy", examImportance: "high", tags: ["Avogadro", "mole"] },
  { id: "chem11-c1-mole-003", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "formula", front: "What is the formula for number of moles?", back: "n = mass / molar mass = N / N_A (where N_A = Avogadro's number)", difficulty: "easy", examImportance: "high", tags: ["mole", "formula"] },
  { id: "chem11-c1-mole-004", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "definition", front: "What is molar mass?", back: "The mass of 1 mole of a substance, expressed in g/mol. Numerically equal to atomic/molecular mass in u.", difficulty: "easy", examImportance: "high", tags: ["molar mass", "definition"] },
  { id: "chem11-c1-mole-005", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "numerical", front: "How many molecules are in 36 g of water (H₂O)?", back: "Moles = 36/18 = 2 mol. Molecules = 2 × 6.022×10²³ = 1.2044×10²⁴.", difficulty: "medium", examImportance: "high", tags: ["numerical", "mole"] },
  { id: "chem11-c1-mole-006", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Mole Concept", type: "numerical", front: "What is the mass of 1 mole of CO₂?", back: "Molar mass = 12 + 2(16) = 44 g/mol. So 1 mole = 44 g.", difficulty: "easy", examImportance: "high", tags: ["numerical", "molar mass"] },
  { id: "chem11-c1-emp-007", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Empirical and Molecular Formula", type: "definition", front: "What is an empirical formula?", back: "The simplest whole-number ratio of atoms of each element in a compound. Example: CH₂O for glucose (C₆H₁₂O₆).", difficulty: "medium", examImportance: "high", tags: ["empirical formula"] },
  { id: "chem11-c1-emp-008", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Empirical and Molecular Formula", type: "definition", front: "What is a molecular formula?", back: "The actual number of atoms of each element in a molecule. It is a whole-number multiple of the empirical formula.", difficulty: "medium", examImportance: "high", tags: ["molecular formula"] },
  { id: "chem11-c1-emp-009", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Empirical and Molecular Formula", type: "concept", front: "Relationship between empirical and molecular formula?", back: "Molecular formula = n × empirical formula, where n = molecular mass / empirical formula mass.", difficulty: "medium", examImportance: "high", tags: ["empirical", "molecular", "relationship"] },
  { id: "chem11-c1-emp-010", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Empirical and Molecular Formula", type: "numerical", front: "A compound has 40% C, 6.67% H, 53.33% O. Molecular mass = 180. Find the molecular formula.", back: "Empirical = CH₂O (mass 30). n = 180/30 = 6. Molecular = C₆H₁₂O₆ (glucose).", difficulty: "hard", examImportance: "high", tags: ["numerical", "molecular formula"] },
  { id: "chem11-c1-stoi-011", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Stoichiometry", type: "definition", front: "What is stoichiometry?", back: "The calculation of reactants and products in chemical reactions using balanced chemical equations.", difficulty: "easy", examImportance: "high", tags: ["stoichiometry"] },
  { id: "chem11-c1-stoi-012", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Stoichiometry", type: "definition", front: "What is a limiting reagent?", back: "The reactant that is completely consumed first in a reaction, limiting the amount of product formed.", difficulty: "medium", examImportance: "high", tags: ["limiting reagent"] },
  { id: "chem11-c1-stoi-013", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Stoichiometry", type: "concept", front: "Why is the limiting reagent important?", back: "It determines the maximum amount of product that can be formed. The other reactants are in excess.", difficulty: "medium", examImportance: "high", tags: ["limiting reagent", "concept"] },
  { id: "chem11-c1-stoi-014", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Stoichiometry", type: "numerical", front: "In the reaction 2H₂ + O₂ → 2H₂O, if 4 g H₂ and 32 g O₂ react, which is the limiting reagent?", back: "Moles H₂ = 4/2 = 2, moles O₂ = 32/32 = 1. Needed: 2 mol H₂ per 1 mol O₂. Both are exactly stoichiometric — neither is limiting.", difficulty: "hard", examImportance: "high", tags: ["numerical", "limiting reagent"] },
  { id: "chem11-c1-comp-015", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Percentage Composition", type: "formula", front: "Formula for percentage composition of an element?", back: "% of element = (mass of element in compound / molar mass of compound) × 100", difficulty: "easy", examImportance: "high", tags: ["percentage composition", "formula"] },
  { id: "chem11-c1-comp-016", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Percentage Composition", type: "numerical", front: "What is the percentage of oxygen in water (H₂O)?", back: "O% = (16/18) × 100 = 88.89%", difficulty: "easy", examImportance: "high", tags: ["numerical", "percentage"] },
  { id: "chem11-c1-conc-017", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Concentration", type: "definition", front: "What is molarity?", back: "Number of moles of solute per litre of solution. Unit: mol/L or M.", difficulty: "easy", examImportance: "high", tags: ["molarity", "concentration"] },
  { id: "chem11-c1-conc-018", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Concentration", type: "formula", front: "Formula for molarity?", back: "M = moles of solute / volume of solution in litres", difficulty: "easy", examImportance: "high", tags: ["molarity", "formula"] },
  { id: "chem11-c1-conc-019", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Concentration", type: "definition", front: "What is molality?", back: "Number of moles of solute per kg of solvent. Unit: mol/kg or m. Independent of temperature.", difficulty: "medium", examImportance: "high", tags: ["molality", "concentration"] },
  { id: "chem11-c1-conc-020", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Concentration", type: "difference", front: "Difference between molarity and molality?", back: "Molarity = mol/L of solution (depends on temperature). Molality = mol/kg of solvent (independent of temperature).", difficulty: "medium", examImportance: "high", tags: ["molarity", "molality", "difference"] },
  { id: "chem11-c1-laws-021", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Laws of Chemical Combination", type: "law", front: "State the law of conservation of mass.", back: "Mass can neither be created nor destroyed in a chemical reaction. Total mass of reactants = total mass of products.", difficulty: "easy", examImportance: "medium", tags: ["law", "conservation of mass"] },
  { id: "chem11-c1-laws-022", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Laws of Chemical Combination", type: "law", front: "State the law of definite proportions.", back: "A given compound always contains the same elements combined in the same proportion by mass, regardless of its source.", difficulty: "medium", examImportance: "medium", tags: ["law", "definite proportions"] },
  { id: "chem11-c1-laws-023", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Laws of Chemical Combination", type: "law", front: "State the law of multiple proportions.", back: "When two elements combine to form more than one compound, the different masses of one element that combine with a fixed mass of the other are in a simple whole-number ratio.", difficulty: "hard", examImportance: "medium", tags: ["law", "multiple proportions"] },
  { id: "chem11-c1-laws-024", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Laws of Chemical Combination", type: "law", front: "State Avogadro's law.", back: "Equal volumes of all gases at the same temperature and pressure contain equal numbers of molecules.", difficulty: "medium", examImportance: "high", tags: ["Avogadro's law", "gas laws"] },
  { id: "chem11-c1-misc-025", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What is an atomic mass unit (u)?", back: "1/12th of the mass of a carbon-12 atom. 1 u ≈ 1.66 × 10⁻²⁴ g.", difficulty: "medium", examImportance: "medium", tags: ["atomic mass unit", "u"] },
  { id: "chem11-c1-misc-026", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What are isotopes?", back: "Atoms of the same element with the same atomic number but different mass numbers (different neutron count).", difficulty: "easy", examImportance: "high", tags: ["isotopes"] },
  { id: "chem11-c1-misc-027", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "concept", front: "How is average atomic mass calculated?", back: "Average atomic mass = Σ(isotope mass × fractional abundance) for all naturally occurring isotopes.", difficulty: "medium", examImportance: "medium", tags: ["average atomic mass", "isotopes"] },
  { id: "chem11-c1-misc-028", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to approach stoichiometry problems?", back: "1) Balance the equation. 2) Convert given masses to moles. 3) Use mole ratio from balanced equation. 4) Identify limiting reagent. 5) Calculate product in moles. 6) Convert to mass if needed.", difficulty: "medium", examImportance: "high", tags: ["exam tip", "stoichiometry"] },
  { id: "chem11-c1-misc-029", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "mistake", front: "Common mistake in molarity calculations?", back: "Using mass of solvent instead of volume of solution. Molarity uses volume of the entire solution, not just the solvent.", difficulty: "medium", examImportance: "high", tags: ["mistake", "molarity"] },
  { id: "chem11-c1-misc-030", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "numerical", front: "Calculate the molarity of a solution containing 5.85 g NaCl in 500 mL solution.", back: "Moles NaCl = 5.85/58.5 = 0.1. Molarity = 0.1/0.5 = 0.2 M.", difficulty: "medium", examImportance: "high", tags: ["numerical", "molarity"] },
  { id: "chem11-c1-misc-031", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "concept", front: "What is the difference between atoms and molecules?", back: "Atoms are the smallest particle of an element that can take part in a chemical reaction. Molecules are combinations of two or more atoms held together by chemical bonds.", difficulty: "easy", examImportance: "medium", tags: ["atoms", "molecules"] },
  { id: "chem11-c1-misc-032", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What is a balanced chemical equation?", back: "An equation where the number of atoms of each element is equal on both sides, obeying the law of conservation of mass.", difficulty: "easy", examImportance: "high", tags: ["balanced equation"] },
  { id: "chem11-c1-misc-033", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "mistake", front: "Common mistake when balancing equations?", back: "Changing subscripts instead of coefficients. You can only change coefficients (the numbers in front). Subscripts define the compound.", difficulty: "medium", examImportance: "high", tags: ["mistake", "balancing"] },
  { id: "chem11-c1-misc-034", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What is the significance of a balanced equation?", back: "It gives the mole ratios of reactants and products, allowing stoichiometric calculations.", difficulty: "medium", examImportance: "medium", tags: ["balanced equation", "significance"] },
  { id: "chem11-c1-misc-035", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "jee", front: "JEE: 20 g of CaCO₃ decomposes: CaCO₃ → CaO + CO₂. What volume of CO₂ at STP?", back: "Moles CaCO₃ = 20/100 = 0.2. At STP, 1 mol gas = 22.4 L. Volume CO₂ = 0.2 × 22.4 = 4.48 L.", difficulty: "hard", examImportance: "high", tags: ["JEE", "stoichiometry", "gas volume"] },
  { id: "chem11-c1-misc-036", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What is the difference between precision and accuracy in chemistry?", back: "Precision = reproducibility of measurements. Accuracy = closeness to true value. Good technique needs both.", difficulty: "medium", examImportance: "medium", tags: ["precision", "accuracy"] },
  { id: "chem11-c1-misc-037", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "concept", front: "What are significant figures rules for zeros?", back: "Leading zeros: not significant. Trailing zeros after decimal: significant. Trailing zeros in whole number without decimal: ambiguous (use scientific notation).", difficulty: "medium", examImportance: "medium", tags: ["significant figures", "zeros"] },
  { id: "chem11-c1-misc-038", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "definition", front: "What is the SI base unit for amount of substance?", back: "Mole (mol) — one of the seven SI base units.", difficulty: "easy", examImportance: "medium", tags: ["SI", "mole"] },
  { id: "chem11-c1-misc-039", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to identify the limiting reagent quickly?", back: "Calculate moles of each reactant. Divide by the stoichiometric coefficient. The smallest value is the limiting reagent.", difficulty: "medium", examImportance: "high", tags: ["exam tip", "limiting reagent"] },
  { id: "chem11-c1-misc-040", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c1", chapter: "Some Basic Concepts of Chemistry", topic: "Miscellaneous", type: "numerical", front: "How many atoms are in 0.5 mol of CH₄?", back: "Each CH₄ has 5 atoms (1 C + 4 H). Atoms = 0.5 × 6.022×10²³ × 5 = 1.5055×10²⁴ atoms.", difficulty: "medium", examImportance: "medium", tags: ["numerical", "atoms", "mole"] },

  // ===== STRUCTURE OF ATOM (c2) — 40 cards =====
  { id: "chem11-c2-atom-001", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Structure", type: "definition", front: "What is atomic number (Z)?", back: "The number of protons in the nucleus of an atom. It determines the element.", difficulty: "easy", examImportance: "high", tags: ["atomic number"] },
  { id: "chem11-c2-atom-002", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Structure", type: "definition", front: "What is mass number (A)?", back: "The sum of protons and neutrons in the nucleus: A = Z + N.", difficulty: "easy", examImportance: "high", tags: ["mass number"] },
  { id: "chem11-c2-atom-003", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Structure", type: "definition", front: "What are isotopes?", back: "Atoms with the same atomic number but different mass numbers (same protons, different neutrons).", difficulty: "easy", examImportance: "high", tags: ["isotopes"] },
  { id: "chem11-c2-atom-004", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Structure", type: "definition", front: "What are isobars?", back: "Atoms with the same mass number but different atomic numbers (different elements). Example: ⁴⁰Ar, ⁴⁰Ca.", difficulty: "medium", examImportance: "medium", tags: ["isobars"] },
  { id: "chem11-c2-atom-005", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Structure", type: "concept", front: "What are cathode rays?", back: "Streams of electrons emitted from the cathode in a discharge tube. They carry negative charge.", difficulty: "medium", examImportance: "medium", tags: ["cathode rays", "electrons"] },
  { id: "chem11-c2-bohr-006", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Bohr's Model", type: "law", front: "State Bohr's postulate about stationary orbits.", back: "Electrons revolve around the nucleus only in certain fixed circular orbits where they do not radiate energy.", difficulty: "medium", examImportance: "high", tags: ["Bohr", "orbits"] },
  { id: "chem11-c2-bohr-007", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Bohr's Model", type: "formula", front: "Bohr's formula for radius of nth orbit (H atom)?", back: "r_n = 0.529 × n² Å (where n = 1, 2, 3, ...)", difficulty: "hard", examImportance: "medium", tags: ["Bohr", "radius", "formula"] },
  { id: "chem11-c2-bohr-008", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Bohr's Model", type: "formula", front: "Bohr's formula for energy of nth orbit (H atom)?", back: "E_n = -13.6/n² eV (negative means bound state)", difficulty: "hard", examImportance: "high", tags: ["Bohr", "energy", "formula"] },
  { id: "chem11-c2-bohr-009", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Bohr's Model", type: "concept", front: "What happens when an electron jumps from higher to lower orbit?", back: "Energy is emitted as a photon: E = hν = E_higher - E_lower.", difficulty: "medium", examImportance: "high", tags: ["Bohr", "energy emission"] },
  { id: "chem11-c2-quantum-010", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Quantum Numbers", type: "definition", front: "What are quantum numbers?", back: "A set of four numbers that completely describe an electron in an atom: n, l, m, s.", difficulty: "medium", examImportance: "high", tags: ["quantum numbers"] },
  { id: "chem11-c2-quantum-011", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Quantum Numbers", type: "definition", front: "What does the principal quantum number (n) describe?", back: "The main energy level/shell. n = 1, 2, 3, ... Determines size and energy of the orbit.", difficulty: "easy", examImportance: "high", tags: ["quantum numbers", "n"] },
  { id: "chem11-c2-quantum-012", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Quantum Numbers", type: "definition", front: "What does the azimuthal quantum number (l) describe?", back: "The shape of the subshell/orbital. l = 0 to (n-1). l=0 is s, l=1 is p, l=2 is d, l=3 is f.", difficulty: "medium", examImportance: "high", tags: ["quantum numbers", "l"] },
  { id: "chem11-c2-quantum-013", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Quantum Numbers", type: "definition", front: "What does the magnetic quantum number (m) describe?", back: "The orientation of the orbital in space. m = -l to +l (including 0), giving 2l+1 values.", difficulty: "medium", examImportance: "high", tags: ["quantum numbers", "m"] },
  { id: "chem11-c2-quantum-014", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Quantum Numbers", type: "definition", front: "What does the spin quantum number (s) describe?", back: "The spin of the electron. s = +½ (clockwise) or -½ (anticlockwise).", difficulty: "easy", examImportance: "high", tags: ["quantum numbers", "spin"] },
  { id: "chem11-c2-orb-015", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Orbitals", type: "concept", front: "How many orbitals are in the p subshell?", back: "Three (pₓ, pᵧ, p_z), each can hold 2 electrons. Total p capacity = 6 electrons.", difficulty: "easy", examImportance: "high", tags: ["orbitals", "p subshell"] },
  { id: "chem11-c2-orb-016", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Orbitals", type: "concept", front: "How many orbitals are in the d subshell?", back: "Five, each can hold 2 electrons. Total d capacity = 10 electrons.", difficulty: "easy", examImportance: "high", tags: ["orbitals", "d subshell"] },
  { id: "chem11-c2-orb-017", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Orbitals", type: "definition", front: "What is the shape of an s orbital?", back: "Spherical — symmetric around the nucleus.", difficulty: "easy", examImportance: "medium", tags: ["s orbital", "shape"] },
  { id: "chem11-c2-orb-018", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Orbitals", type: "definition", front: "What is the shape of a p orbital?", back: "Dumbbell — two lobes along an axis (x, y, or z).", difficulty: "easy", examImportance: "medium", tags: ["p orbital", "shape"] },
  { id: "chem11-c2-prin-019", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "law", front: "State the Aufbau principle.", back: "Electrons fill orbitals in order of increasing energy: 1s < 2s < 2p < 3s < 3p < 4s < 3d < 4p ...", difficulty: "medium", examImportance: "high", tags: ["Aufbau", "electron configuration"] },
  { id: "chem11-c2-prin-020", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "law", front: "State the Pauli exclusion principle.", back: "No two electrons in an atom can have the same set of four quantum numbers. An orbital can hold max 2 electrons with opposite spins.", difficulty: "medium", examImportance: "high", tags: ["Pauli", "exclusion principle"] },
  { id: "chem11-c2-prin-021", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "law", front: "State Hund's rule of maximum multiplicity.", back: "Electrons occupy orbitals of equal energy singly before pairing up. All singly occupied orbitals have parallel spins.", difficulty: "medium", examImportance: "high", tags: ["Hund's rule"] },
  { id: "chem11-c2-prin-022", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "application", front: "What is the electronic configuration of nitrogen (Z=7)?", back: "1s² 2s² 2p³ (three p-electrons occupy separate p orbitals: 2pₓ¹ 2pᵧ¹ 2p_z¹)", difficulty: "medium", examImportance: "high", tags: ["configuration", "nitrogen"] },
  { id: "chem11-c2-prin-023", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "application", front: "What is the electronic configuration of sodium (Z=11)?", back: "1s² 2s² 2p⁶ 3s¹", difficulty: "easy", examImportance: "high", tags: ["configuration", "sodium"] },
  { id: "chem11-c2-prin-024", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Electronic Configuration", type: "mistake", front: "Common mistake in writing electronic configurations?", back: "Not following Hund's rule. For example, writing 2pₓ² 2pᵧ¹ instead of 2pₓ¹ 2pᵧ¹ 2p_z¹ for p³ configuration.", difficulty: "medium", examImportance: "high", tags: ["mistake", "Hund's rule"] },
  { id: "chem11-c2-dual-025", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Dual Nature", type: "concept", front: "What is the de Broglie wavelength?", back: "λ = h/p = h/(mv), where h = Planck's constant, m = mass, v = velocity. Shows matter has wave nature.", difficulty: "hard", examImportance: "high", tags: ["de Broglie", "wavelength"] },
  { id: "chem11-c2-dual-026", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Dual Nature", type: "concept", front: "What is the Heisenberg uncertainty principle?", back: "It is impossible to simultaneously determine the exact position and momentum of an electron: Δx · Δp ≥ h/(4π).", difficulty: "hard", examImportance: "high", tags: ["Heisenberg", "uncertainty"] },
  { id: "chem11-c2-dual-027", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Dual Nature", type: "mistake", front: "Common misconception about Heisenberg's principle?", back: "Thinking it's a limitation of instruments. It's a fundamental property of nature — even perfect instruments cannot overcome it.", difficulty: "hard", examImportance: "medium", tags: ["mistake", "Heisenberg"] },
  { id: "chem11-c2-spec-028", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Spectra", type: "definition", front: "What is an atomic spectrum?", back: "The pattern of lines produced when light from an excited atom is passed through a prism/spectroscope. Each element has a unique spectrum.", difficulty: "medium", examImportance: "medium", tags: ["atomic spectrum"] },
  { id: "chem11-c2-spec-029", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Spectra", type: "formula", front: "Rydberg formula for hydrogen spectrum?", back: "1/λ = R(1/n₁² - 1/n₂²), where R = 1.097×10⁷ m⁻¹, n₂ > n₁.", difficulty: "hard", examImportance: "medium", tags: ["Rydberg", "spectrum"] },
  { id: "chem11-c2-spec-030", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Atomic Spectra", type: "concept", front: "What are the Lyman, Balmer, and Paschen series?", back: "Lyman: transitions to n=1 (UV). Balmer: to n=2 (visible). Paschen: to n=3 (IR).", difficulty: "medium", examImportance: "medium", tags: ["spectral series"] },
  { id: "chem11-c2-misc-031", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "definition", front: "What is Planck's quantum theory?", back: "Energy is emitted or absorbed in discrete packets (quanta): E = hν, where h = 6.626×10⁻³⁴ J·s.", difficulty: "medium", examImportance: "high", tags: ["Planck", "quantum"] },
  { id: "chem11-c2-misc-032", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "formula", front: "What is the photoelectric effect equation?", back: "hν = KE_max + φ (work function), where φ is the minimum energy to eject an electron.", difficulty: "hard", examImportance: "medium", tags: ["photoelectric", "Einstein"] },
  { id: "chem11-c2-misc-033", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "concept", front: "What is the maximum number of electrons in a shell?", back: "2n², where n is the principal quantum number. n=1: 2, n=2: 8, n=3: 18, n=4: 32.", difficulty: "easy", examImportance: "high", tags: ["electron capacity", "2n²"] },
  { id: "chem11-c2-misc-034", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "concept", front: "Why do noble gases not react easily?", back: "They have a completely filled outer shell (ns²np⁶ = octet), making them stable and unreactive.", difficulty: "easy", examImportance: "medium", tags: ["noble gases", "stability"] },
  { id: "chem11-c2-misc-035", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to quickly write electronic configuration?", back: "Use the diagonal method (Madelung rule): fill 1s→2s→2p→3s→3p→4s→3d→4p→5s→4d→5p→6s... Remember max capacity: s=2, p=6, d=10, f=14.", difficulty: "medium", examImportance: "high", tags: ["exam tip", "configuration"] },
  { id: "chem11-c2-misc-036", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "jee", front: "JEE: What is the energy of an electron in the 2nd orbit of hydrogen?", back: "E₂ = -13.6/n² = -13.6/4 = -3.4 eV", difficulty: "medium", examImportance: "high", tags: ["JEE", "Bohr", "energy"] },
  { id: "chem11-c2-misc-037", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "definition", front: "What is the threshold frequency?", back: "The minimum frequency of light needed to eject electrons in the photoelectric effect: ν₀ = φ/h.", difficulty: "hard", examImportance: "medium", tags: ["threshold frequency", "photoelectric"] },
  { id: "chem11-c2-misc-038", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "concept", front: "What is the difference between orbit and orbital?", back: "Orbit: a fixed circular path (Bohr model). Orbital: a 3D region where an electron can be found with high probability (quantum model).", difficulty: "medium", examImportance: "high", tags: ["orbit", "orbital", "difference"] },
  { id: "chem11-c2-misc-039", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "numerical", front: "Calculate the de Broglie wavelength of an electron with velocity 10⁶ m/s (m = 9.1×10⁻³¹ kg, h = 6.6×10⁻³⁴ J·s).", back: "λ = h/(mv) = 6.6×10⁻³⁴ / (9.1×10⁻³¹ × 10⁶) = 7.25×10⁻¹⁰ m = 7.25 Å", difficulty: "hard", examImportance: "medium", tags: ["numerical", "de Broglie"] },
  { id: "chem11-c2-misc-040", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c2", chapter: "Structure of Atom", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: Remember the order of orbital filling?", back: "Use the 'n+l' rule: lower n+l fills first. If n+l is equal, lower n fills first. Example: 4s (n+l=4) fills before 3d (n+l=5).", difficulty: "medium", examImportance: "high", tags: ["exam tip", "n+l rule"] },

  // ===== CHEMICAL BONDING (c4) — 40 cards =====
  { id: "chem11-c4-ionic-001", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Ionic Bond", type: "definition", front: "What is an ionic bond?", back: "A bond formed by complete transfer of electrons from one atom to another, creating cations and anions held by electrostatic attraction.", difficulty: "easy", examImportance: "high", tags: ["ionic bond"] },
  { id: "chem11-c4-ionic-002", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Ionic Bond", type: "concept", front: "What conditions favor ionic bond formation?", back: "Low ionization enthalpy of metal (easily loses electrons) + high electron gain enthalpy of non-metal (easily gains electrons). Large lattice energy also helps.", difficulty: "medium", examImportance: "high", tags: ["ionic bond", "conditions"] },
  { id: "chem11-c4-cov-003", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Covalent Bond", type: "definition", front: "What is a covalent bond?", back: "A bond formed by sharing of electron pairs between two atoms. Example: H₂ shares 2 electrons.", difficulty: "easy", examImportance: "high", tags: ["covalent bond"] },
  { id: "chem11-c4-cov-004", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Covalent Bond", type: "definition", front: "What is a coordinate (dative) bond?", back: "A covalent bond where both electrons come from one atom (donor) and are shared with another (acceptor). Example: NH₄⁺.", difficulty: "medium", examImportance: "high", tags: ["coordinate bond", "dative"] },
  { id: "chem11-c4-octet-005", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Octet Rule", type: "law", front: "State the octet rule.", back: "Atoms tend to gain, lose, or share electrons to achieve 8 electrons in their outer shell (noble gas configuration).", difficulty: "easy", examImportance: "high", tags: ["octet rule"] },
  { id: "chem11-c4-octet-006", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Octet Rule", type: "concept", front: "Which molecules are exceptions to the octet rule?", back: "1) Incomplete octet: BeCl₂, BF₃. 2) Expanded octet: PCl₅, SF₆. 3) Odd electron: NO, NO₂.", difficulty: "medium", examImportance: "high", tags: ["octet rule", "exceptions"] },
  { id: "chem11-c4-formal-007", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Formal Charge", type: "formula", front: "Formula for formal charge?", back: "FC = (valence e⁻) - (non-bonding e⁻) - ½(bonding e⁻)", difficulty: "medium", examImportance: "high", tags: ["formal charge", "formula"] },
  { id: "chem11-c4-formal-008", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Formal Charge", type: "concept", front: "What is the significance of formal charge?", back: "The Lewis structure with formal charges closest to zero is the most stable (preferred) structure.", difficulty: "medium", examImportance: "medium", tags: ["formal charge", "significance"] },
  { id: "chem11-c4-res-009", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Resonance", type: "definition", front: "What is resonance?", back: "When a single Lewis structure cannot describe a molecule, multiple structures (resonance structures) are used. The actual structure is a hybrid.", difficulty: "medium", examImportance: "high", tags: ["resonance"] },
  { id: "chem11-c4-res-010", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Resonance", type: "application", front: "Give an example of resonance.", back: "Ozone (O₃) has two resonance structures with a double bond shifting between the two O-O bonds. The actual structure has equivalent bonds (1.5 bond order).", difficulty: "medium", examImportance: "medium", tags: ["resonance", "ozone"] },
  { id: "chem11-c4-vsepr-011", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "definition", front: "What is VSEPR theory?", back: "Valence Shell Electron Pair Repulsion — electron pairs around a central atom arrange themselves to minimize repulsion, determining molecular geometry.", difficulty: "medium", examImportance: "high", tags: ["VSEPR"] },
  { id: "chem11-c4-vsepr-012", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "concept", front: "What is the shape of a molecule with 2 bond pairs and 0 lone pairs (like BeCl₂)?", back: "Linear, with a bond angle of 180°.", difficulty: "easy", examImportance: "high", tags: ["VSEPR", "linear"] },
  { id: "chem11-c4-vsepr-013", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "concept", front: "What is the shape of a molecule with 3 bond pairs and 0 lone pairs (like BF₃)?", back: "Trigonal planar, with a bond angle of 120°.", difficulty: "easy", examImportance: "high", tags: ["VSEPR", "trigonal planar"] },
  { id: "chem11-c4-vsepr-014", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "concept", front: "What is the shape of a molecule with 4 bond pairs and 0 lone pairs (like CH₄)?", back: "Tetrahedral, with a bond angle of 109.5°.", difficulty: "easy", examImportance: "high", tags: ["VSEPR", "tetrahedral"] },
  { id: "chem11-c4-vsepr-015", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "concept", front: "What is the shape of a molecule with 3 bond pairs and 1 lone pair (like NH₃)?", back: "Pyramidal (trigonal pyramidal), with a bond angle of ~107° (less than 109.5° due to lone pair repulsion).", difficulty: "medium", examImportance: "high", tags: ["VSEPR", "pyramidal"] },
  { id: "chem11-c4-vsepr-016", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "concept", front: "What is the shape of a molecule with 2 bond pairs and 2 lone pairs (like H₂O)?", back: "V-shaped (bent), with a bond angle of ~104.5° (further reduced by two lone pairs).", difficulty: "medium", examImportance: "high", tags: ["VSEPR", "bent"] },
  { id: "chem11-c4-vsepr-017", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "VSEPR Theory", type: "mistake", front: "Common mistake with VSEPR?", back: "Forgetting that lone pairs repel more than bond pairs. Lone pair-lone pair > lone pair-bond pair > bond pair-bond pair repulsion.", difficulty: "medium", examImportance: "high", tags: ["mistake", "VSEPR"] },
  { id: "chem11-c4-hyb-018", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hybridisation", type: "definition", front: "What is hybridisation?", back: "The mixing of atomic orbitals of similar energies to form new hybrid orbitals of equal energy and shape.", difficulty: "medium", examImportance: "high", tags: ["hybridisation"] },
  { id: "chem11-c4-hyb-019", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hybridisation", type: "concept", front: "What is the hybridisation of carbon in CH₄?", back: "sp³ — four equivalent hybrid orbitals forming four C-H sigma bonds, tetrahedral geometry.", difficulty: "medium", examImportance: "high", tags: ["hybridisation", "sp3"] },
  { id: "chem11-c4-hyb-020", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hybridisation", type: "concept", front: "What is the hybridisation of carbon in C₂H₄ (ethene)?", back: "sp² — three hybrid orbitals form sigma bonds, one unhybridized p orbital forms the pi bond. Planar geometry.", difficulty: "medium", examImportance: "high", tags: ["hybridisation", "sp2"] },
  { id: "chem11-c4-hyb-021", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hybridisation", type: "concept", front: "What is the hybridisation of carbon in C₂H₂ (ethyne)?", back: "sp — two hybrid orbitals form sigma bonds, two unhybridized p orbitals form two pi bonds. Linear geometry.", difficulty: "medium", examImportance: "high", tags: ["hybridisation", "sp"] },
  { id: "chem11-c4-bonds-022", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Sigma and Pi Bonds", type: "definition", front: "What is a sigma (σ) bond?", back: "A bond formed by head-on (axial) overlap of orbitals. It is the strongest type of covalent bond. Every single bond is a sigma bond.", difficulty: "medium", examImportance: "high", tags: ["sigma bond"] },
  { id: "chem11-c4-bonds-023", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Sigma and Pi Bonds", type: "definition", front: "What is a pi (π) bond?", back: "A bond formed by sideways (lateral) overlap of p orbitals. Weaker than sigma. A double bond has 1σ + 1π; a triple bond has 1σ + 2π.", difficulty: "medium", examImportance: "high", tags: ["pi bond"] },
  { id: "chem11-c4-bonds-024", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Sigma and Pi Bonds", type: "mistake", front: "Common mistake about sigma and pi bonds?", back: "Thinking a double bond is twice as strong as a single bond. A double bond (1σ+1π) is stronger but less than twice, because π bond is weaker than σ.", difficulty: "medium", examImportance: "medium", tags: ["mistake", "sigma", "pi"] },
  { id: "chem11-c4-hb-025", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hydrogen Bonding", type: "definition", front: "What is hydrogen bonding?", back: "An attractive force between H (covalently bonded to N, O, or F) and an electronegative atom of another molecule. Stronger than dipole-dipole, weaker than covalent.", difficulty: "medium", examImportance: "high", tags: ["hydrogen bonding"] },
  { id: "chem11-c4-hb-026", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Hydrogen Bonding", type: "concept", front: "Why does water have an unusually high boiling point?", back: "Due to extensive hydrogen bonding between H₂O molecules. Each water molecule can form 4 H-bonds.", difficulty: "medium", examImportance: "high", tags: ["hydrogen bonding", "water"] },
  { id: "chem11-c4-dip-027", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Dipole Moment", type: "definition", front: "What is dipole moment?", back: "The product of charge and distance between charges: μ = q × d. Unit: Debye (D). Measures polarity of a molecule.", difficulty: "medium", examImportance: "high", tags: ["dipole moment"] },
  { id: "chem11-c4-dip-028", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Dipole Moment", type: "concept", front: "Why is CO₂ nonpolar even though C=O bonds are polar?", back: "CO₂ is linear, so the two C=O dipoles cancel each other. Net dipole moment = 0.", difficulty: "medium", examImportance: "high", tags: ["dipole moment", "CO2"] },
  { id: "chem11-c4-dip-029", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Dipole Moment", type: "concept", front: "Why is H₂O polar?", back: "H₂O is bent (V-shaped), so the two O-H dipoles do not cancel. Net dipole moment ≠ 0.", difficulty: "medium", examImportance: "high", tags: ["dipole moment", "water"] },
  { id: "chem11-c4-bp-030", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Bond Parameters", type: "definition", front: "What is bond order?", back: "The number of bonds between two atoms. Single=1, double=2, triple=3. Higher bond order = shorter, stronger bond.", difficulty: "easy", examImportance: "high", tags: ["bond order"] },
  { id: "chem11-c4-bp-031", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Bond Parameters", type: "concept", front: "What is the relationship between bond length and bond strength?", back: "Inverse — shorter bonds are stronger. Triple bonds (shortest) > double > single (longest) in strength.", difficulty: "easy", examImportance: "high", tags: ["bond length", "bond strength"] },
  { id: "chem11-c4-misc-032", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "difference", front: "Difference between ionic and covalent compounds?", back: "Ionic: high melting point, conduct in solution, crystalline solids. Covalent: low melting point, usually don't conduct, exist as molecules or network solids.", difficulty: "medium", examImportance: "high", tags: ["ionic", "covalent", "difference"] },
  { id: "chem11-c4-misc-033", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "concept", front: "What is the order of intermolecular forces strength?", back: "Hydrogen bonding > dipole-dipole > London dispersion (van der Waals). All are weaker than ionic/covalent bonds.", difficulty: "medium", examImportance: "medium", tags: ["intermolecular forces"] },
  { id: "chem11-c4-misc-034", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "application", front: "What is the hybridisation and shape of SF₆?", back: "sp³d² hybridisation, octahedral shape, with 90° bond angles.", difficulty: "hard", examImportance: "medium", tags: ["hybridisation", "SF6"] },
  { id: "chem11-c4-misc-035", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "application", front: "What is the hybridisation and shape of PCl₅?", back: "sp³d hybridisation, trigonal bipyramidal shape, with 90° and 120° bond angles.", difficulty: "hard", examImportance: "medium", tags: ["hybridisation", "PCl5"] },
  { id: "chem11-c4-misc-036", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to determine hybridisation quickly?", back: "Count steric number = (number of bonded atoms + number of lone pairs on central atom). 2=sp, 3=sp², 4=sp³, 5=sp³d, 6=sp³d².", difficulty: "medium", examImportance: "high", tags: ["exam tip", "hybridisation"] },
  { id: "chem11-c4-misc-037", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "mistake", front: "Common mistake with lone pairs in VSEPR?", back: "Counting lone pairs as bond pairs for geometry. The molecular shape considers only atoms, but electron pair geometry includes lone pairs.", difficulty: "medium", examImportance: "high", tags: ["mistake", "VSEPR", "lone pairs"] },
  { id: "chem11-c4-misc-038", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "jee", front: "JEE: How many sigma and pi bonds are in a molecule of benzene (C₆H₆)?", back: "12 sigma bonds (6 C-C + 6 C-H) and 3 pi bonds (alternating C=C). Total = 15 bonds.", difficulty: "hard", examImportance: "high", tags: ["JEE", "benzene", "sigma", "pi"] },
  { id: "chem11-c4-misc-039", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "concept", front: "Why are noble gases monoatomic?", back: "They have completely filled outer shells (octet), so they have no tendency to form bonds with other atoms.", difficulty: "easy", examImportance: "medium", tags: ["noble gases", "monoatomic"] },
  { id: "chem11-c4-misc-040", subject: "chemistry" as any, subjectName: "Chemistry", chapterId: "c4", chapter: "Chemical Bonding and Molecular Structure", topic: "Miscellaneous", type: "definition", front: "What is bond enthalpy?", back: "The energy required to break 1 mole of bonds in gaseous state. Higher bond enthalpy = stronger bond. Unit: kJ/mol.", difficulty: "medium", examImportance: "high", tags: ["bond enthalpy"] },
];

export default CHEMISTRY_FLASHCARDS;
